template<class C>
concept Reservable = requires(C& container, std::size_t count) {
    container.reserve(count);
};

// Overload form: a failed call names the unsatisfied concept.
template<class C>
void reserve_concept(C&, std::size_t) {
}

template<Reservable C>
void reserve_concept(C& container, std::size_t count) {
    container.reserve(count);
}

// if constexpr form: one interface, and an error would point into whichever
// branch was selected rather than at an overload set.
template<class C>
void reserve_if_possible(C& container, std::size_t count) {
    if constexpr (Reservable<C>) {
        container.reserve(count);
    } else {
        static_cast<void>(container);
        static_cast<void>(count);
    }
}

void use() {
    std::vector<int> levels;
    std::array<int, 8> fixed{};

    reserve_concept(levels, 32);
    reserve_concept(fixed, 32);
    reserve_if_possible(levels, 32);
    reserve_if_possible(fixed, 32);
}

