#include <cstddef>
#include <new>
#include <utility>

class ObjectPool {
public:
    void* allocate(std::size_t size, std::size_t alignment);
    void release(void* address) noexcept;
};

template<class T, class... Args>
T* make_pooled(ObjectPool& pool, Args&&... arguments) {
    void* storage = pool.allocate(sizeof(T), alignof(T));

    try {
        // Each pack element is forwarded independently, so an lvalue stays an
        // lvalue and a temporary stays movable. Writing T(arguments...) would
        // make every named parameter an lvalue and silently copy.
        return ::new (storage) T(std::forward<Args>(arguments)...);
    } catch (...) {
        pool.release(storage);
        throw;
    }
}

