// Template parameter: the concrete callable type is preserved, so the call
// usually inlines and constants propagate into the loop. Cost: one emitted
// specialization per callable type, and the definition must live in a header.
template<class Handler>
void for_each_level(std::span<const Level> levels, Handler handler) {
    for (const Level& level : levels) {
        handler(level);
    }
}

// Type-erased boundary: one shared implementation, and the .cpp can hide it
// behind this interface. Cost: an indirect call per element that the
// optimizer normally cannot see through.
struct LevelSink {
    virtual void on_level(const Level& level) = 0;
    virtual ~LevelSink() = default;
};

void for_each_level_erased(std::span<const Level> levels, LevelSink& sink);
